"""
================================================================================
二十四山择吉天机模块
================================================================================
提供二十四山详细的择吉规则，包括：
- 山向基本信息（五行属性、分金、天帝太阳到山到向）
- 避忌信息（克山运、冲山、山家三煞、阴府等）
- 流年吉凶定局
- 流月吉凶与吉日定局
- 杨公风水立向择日大吉时

使用方法:
    from modules.二十四山择吉天机 import Mountain择吉Data, get_mountain_data
    
    # 获取壬山丙向数据
    data = get_mountain_data('壬山丙向')
    print(data['basic_info'])
    print(data['avoid_info'])
    print(data['yearly_luck'])
    
    # 获取子山午向数据
    data = get_mountain_data('子山午向')
    
    # 获取杨公风水大吉时
    jishi = get_yang_gong_jishi('甲己')
================================================================================
"""

