def get_yinfu_config(mountain_name, is_after_dongzhi=None):
    """获取指定山向的阴府配置

    Args:
        mountain_name: 山向名称，如"乾山"、"壬山丙向"、"乾山巽向兼亥巳"等
        is_after_dongzhi: 是否已过冬至（None=自动判断, True=冬至后, False=冬至前）
                          用于傍阴府山中需要区分冬至/夏至前后的规则

    Returns:
        dict: 阴府配置，包含 type(正阴府/傍阴府), 忌干, 说明
    """
    # 提取山名（乾山 -> 乾山, 壬山丙向 -> 壬山, 乾山巽向兼亥巳 -> 乾山）
    # 找到"山"字的位置，取"山"字前面的部分
    shan = None

    # 方法1：直接查找以"山"结尾的部分
    if '山' in mountain_name:
        parts = mountain_name.split('山')
        shan = parts[0] + '山'

    # 如果没有找到，直接使用原名称
    if not shan:
        shan = mountain_name

    # 检查是否有兼向
    has_jianxiang = '兼' in mountain_name

    # 如果有兼向，提取兼向山（兼未 -> 未山）
    jian_shan = None
    if has_jianxiang:
        import re
        match = re.search(r'兼(\w+)', mountain_name)
        if match:
            jian_shan = match.group(1) + '山'

    # 优先使用主山（坐山）的阴府规则
    # 如果主山是正阴府山，使用正阴府规则
    if shan in YINFU_CONFIG['正阴府']:
        config = YINFU_CONFIG['正阴府'][shan].copy()
        config['type'] = '正阴府'
        if has_jianxiang and jian_shan:
            config['说明'] = f'{shan}兼{jian_shan}：{config["说明"]}'
        return config

    # 如果主山是傍阴府山，再检查兼向山
    if shan in YINFU_CONFIG['傍阴府']:
        config = YINFU_CONFIG['傍阴府'][shan].copy()
        config['type'] = '傍阴府'
        
        # 根据冬至/夏至前后选择对应的忌干
        if is_after_dongzhi is not None:
            if is_after_dongzhi and '冬至后忌干' in config:
                config['忌干'] = config['冬至后忌干']
            elif not is_after_dongzhi and '夏至后忌干' in config:
                config['忌干'] = config['夏至后忌干']
        
        return config

    return None


class Mountain择吉Data:
    """二十四山择吉数据类"""
    
    def __init__(self, mountain_name):
        self.mountain_name = mountain_name
        self.basic_info = {}
        self.avoid_info = {}
        self.yearly_luck = {}
        self.monthly_luck = {}
        self.bury_monthly_luck = {}


